<template><div class="p-2 app-container"><el-card shadow="never"><template #header><div><h3>Skill 路由与定价</h3><p>一行配置对应一个用户端功能 Skill。用户端不显示模型，优先调用这里的主模型；主模型不可用时自动切换同能力最低价模型。</p></div></template><el-table v-loading="loading" :data="rows" border><el-table-column prop="feature_name" label="功能 / Skill" min-width="150"/><el-table-column prop="feature_code" label="Skill 编码" min-width="145"/><el-table-column label="主模型" min-width="230"><template #default="scope"><el-select v-model="scope.row.gateway_model_id" clearable placeholder="未设主模型时自动路由" style="width:100%"><el-option v-for="m in modelsFor(scope.row)" :key="m.id" :label="`${m.model_name} · ${m.capability}`" :value="m.id"/></el-select></template></el-table-column><el-table-column label="最低扣费" width="190"><template #default="scope"><el-input-number v-model="scope.row.credits_per_call" :min="0" size="small"/></template></el-table-column><el-table-column label="启用" width="100"><template #default="scope"><el-switch v-model="scope.row.enabled" active-value="1" inactive-value="0"/></template></el-table-column><el-table-column label="操作" width="90"><template #default="scope"><el-button link type="primary" @click="save(scope.row)">保存</el-button></template></el-table-column></el-table></el-card></div></template>
<script setup lang="ts">import {listFeatures,updateFeature,listModels} from '@/api/aigc/billing';import modal from '@/plugins/modal';const rows=ref<any[]>([]);const models=ref<any[]>([]);const loading=ref(false);async function load(){loading.value=true;try{const [f,m]:any[]=await Promise.all([listFeatures(),listModels()]);rows.value=f.data||f||[];models.value=m.data||m||[]}finally{loading.value=false}}function modelsFor(row:any){const capability:any={image:'draw',video:'video',music:'music',voice_clone:'audio',avatar_clone:'digital_human',photo_dh:'digital_human',digital_human:'digital_human',face_merge:'face_merge'}[row.feature_code]||'chat';return models.value.filter(m=>m.capability===capability&&String(m.enabled)!=='0')}async function save(row:any){await updateFeature(row.id,{credits:Number(row.credits_per_call),enabled:row.enabled,gatewayModelId:row.gateway_model_id||null});modal.msgSuccess('功能配置已保存')}onMounted(load);</script>
<style scoped>h3{margin:0 0 6px}p{margin:0;color:#8492a6;font-size:13px}</style>
